  [ -f "$PREFIX/master_db.py" ] || [ -f "$PREFIX/data/fs_master.db" ] \
    || die "$PREFIX ê°€ fs-master í´ë”ë¡œ ë³´ì´ì§€ ì•Šì•„ ì‚­ì œí•˜ì§€ ì•ŠìŠµë‹ˆë‹¤."
  if [ "$PURGE" = 1 ]; then
    rm -rf "$PREFIX"
    info "$PREFIX ì „ì²´ ì‚­ì œ (ë“±ë¡ ëª©ë¡Â·ìˆ˜ì§‘ ê²°ê³¼ í¬í•¨)"
  else
